try:
    print('>>> f = getattr')
    print('>>> x = 3')
    print('>>> y = bytearray()')
    print('>>> f(x, y)')
    f = getattr
    x = 3
    y = bytearray()
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
